begin;select plan(10);select has_table('public','salon_charter_rights');select has_function('public','create_salon_charter_sale');select has_function('public','redeem_salon_charter_right');select has_function('public','admin_delete_salon_charter_item');select lives_ok($$select * from public.create_salon_charter_sale('charter_tetiaroa_2j_1n',290000,'A','B','1','',2,false,'tpe','','',null,'[]')$$,'droit sans date');select is((select montant_total from public.salon_sales order by created_at desc limit 1),290000,'prix');select is((select valid_until from public.salon_charter_rights order by created_at desc limit 1),date '2027-01-31','validité');select lives_ok(format($$select public.admin_delete_salon_charter_item(%L,%L)$$,(select sale_id from public.salon_sale_items where activity='charter' limit 1),(select id from public.salon_sale_items where activity='charter' limit 1)),'unused supprimable');select throws_ok($$select * from public.create_salon_charter_sale('charter_tetiaroa_2j_1n',290000,'A','B','1','',10,false,'tpe','','',null,'[]')$$,'22023',null,'plus de 9 refusé');select is((select count(*)::integer from public.reservations_charter where montant_total=290000),0,'aucune réservation fictive');select * from finish();rollback;
